return items.map(item => {
  const r = item.json;
  let expansions = [];
  try { expansions = r.expansions ? JSON.parse(r.expansions) : []; } catch (e) { expansions = []; }
  return {
    json: {
      id: r.game_id,
      bggId: r.bgg_id || null,
      num: r.num || null,
      title: r.title || '',
      genre: r.genre || '',
      type: r.type || '',
      desc: r.desc || '',
      expansions,
      desireToPlay: Number(r.desire_to_play || 0),
      thinningCandidate: !!r.thinning_candidate,
      bggRating: r.bgg_rating || null,
      photoUrl: r.photo_url || null
    }
  };
});
